required={'card':('confetti',['card-2-quiet','card-3-icon3d','card-3-line','card-3-on','card-4','card-5-tone']),'callout':('annual',['callout','callout-icon','callout-stack']),'chart-area':('annual',['area-1','areas-2','areas-stacked-3','area-3pt']),'chart-bar':('confetti',['bars-12','bars-6','bars-3','bars-h-5','bars-h-8','bars-2']),'chart-donut':('amethyst',['donut','donuts-3','donuts-4','donut-0','donut-100']),'chart-line':('amethyst',['lines-12','lines-6','lines-3','lines-flat'])}
for con in contracts:
 folder=mapids[con['id']];roots=con['roots'];rd=Path('elements')/folder
 root=':is('+','.join(f'.{x}[data-el="dockside-{folder}"]' for x in roots)+')'
 base='''R{position:relative;min-width:0;min-height:0;margin:0;color:var(--ink);font-family:var(--font-body);font-size:var(--type-16);font-weight:var(--body-weight);line-height:var(--body-line);letter-spacing:var(--body-track);container-type:size}R *{box-sizing:border-box;min-width:0}R .name{display:block;font-family:var(--font-display);font-size:var(--type-24);font-weight:var(--name-weight);line-height:var(--name-line);letter-spacing:var(--name-track);margin:0;overflow-wrap:anywhere}R .note{font-size:var(--type-16);font-weight:var(--body-weight);line-height:var(--body-line);letter-spacing:var(--body-track);color:var(--n-7);margin:0;overflow-wrap:anywhere}R .kick{font-size:var(--type-14);font-weight:var(--label-weight);line-height:var(--label-line);letter-spacing:var(--label-track);margin:0}R .fig{font-family:var(--font-display);font-size:var(--type-48);line-height:var(--figure-line);font-weight:var(--figure-weight);letter-spacing:var(--figure-track);margin:0}R .fig small{font-size:var(--type-20);font-weight:var(--body-weight)}R .icon{width:32px;height:32px;display:inline-block;flex:none}R p{margin:0}'''
 s=(base+CSS[folder]).replace('R',root)
 # Dynamic member indices and radial positions are data geometry, not decoration copied from any sample.
 for i in range(1,25):
  s+=f'{root}>:nth-child({i}){{--dockside-index:{i-1};}}\n'
 for count in range(3,7):
  for i in range(count):
   angle=-90+i*360/count
   s+=f'{root}:has(>.node:nth-child({count+1}):last-child)>.node:nth-child({i+2}),{root}:has(>.spoke:nth-child({count+1}):last-child)>.spoke:nth-child({i+2}){{--dockside-angle:{angle}deg;}}\n'
 for i in range(1,13):
  s+=f'{root}>.pt:nth-child({i}),{root} .pt:nth-child({i} of .pt){{--dockside-self:--dockside-{folder}-{i};--dockside-prev:--dockside-{folder}-{max(1,i-1)};}}\n'
 if folder=='matrix-nine':
  for i in range(9):s+=f'{root}>.cell:nth-child({i+3}){{grid-column:{i%3+2};grid-row:{i//3+1};}}\n'
